# Exhaustive forward DP over (town, cargo) -> max gold, day by day.
# Within a day: unlimited buy/sell (to closure); then optionally one travel.
WORLD = {"Eastwatch": {"fish": 55, "silk": 44, "timber": 41, "amber": 14},
         "Ashford": {"fish": 37, "silk": 17, "timber": 51, "amber": 46},
         "Marlow": {"fish": 38, "silk": 41, "timber": 59, "amber": 35}}
CAP=20; LAST=8; GOODS=["fish","silk","timber","amber"]
gi = {g:i for i,g in enumerate(GOODS)}
def cargokey(c): return tuple(c)

states = {("Eastwatch",(0,0,0,0)): 250}  # (town,cargo)->max gold
for day in range(1, LAST+1):
    # closure under buy/sell at same town/day (unit steps until no improvement)
    changed = True
    while changed:
        changed = False
        new = dict(states)
        for (town,c), gold in states.items():
            p = WORLD[town]
            tot = sum(c)
            # buys
            for g in GOODS:
                if gold >= p[g] and tot < CAP:
                    c2 = list(c); c2[gi[g]] += 1
                    k = (town, tuple(c2))
                    if new.get(k, -1) < gold - p[g]:
                        new[k] = gold - p[g]; changed = True
            # sells
            for g in GOODS:
                if c[gi[g]] > 0:
                    c2 = list(c); c2[gi[g]] -= 1
                    k = (town, tuple(c2))
                    if new.get(k, -1) < gold + p[g]:
                        new[k] = gold + p[g]; changed = True
        states = new
    if day == LAST: break
    # travel: one step, to any other town
    new = {}
    for (town,c), gold in states.items():
        for t2 in WORLD:
            if t2 != town:
                k = (t2, c)
                if new.get(k, -1) < gold:
                    new[k] = gold
    states = new

