import itertools

WORLD = {"prices": {"Fennick": {"timber": 44, "salt": 26, "spice": 50, "fish": 33}, "Highcliff": {"timber": 12, "salt": 21, "spice": 27, "fish": 10}, "Thornwick": {"timber": 48, "salt": 21, "spice": 36, "fish": 9}, "Dunmere": {"timber": 55, "salt": 60, "spice": 20, "fish": 18}}, "capacity": 40, "last_day": 7}
TOWNS = list(WORLD["prices"])
GOODS = ["timber","salt","spice","fish"]
CAP = 40
MAXBUY = 2400  # budget cap: 40 * max price 60

u = {}
u[7] = {t: dict(WORLD["prices"][t]) for t in TOWNS}
for d in range(6, 0, -1):
    u[d] = {}
    for t in TOWNS:
        u[d][t] = {}
        for i in GOODS:
            best = WORLD["prices"][t][i]
            for t2 in TOWNS:
                if t2 != t:
                    best = max(best, u[d+1][t2][i])
            u[d][t][i] = best

# value of a cargo given day/town
def cargo_value(cargo, d, t):
    return sum(cargo[i]*u[d][t][GOODS[i]] for i in range(4))

# DP state: (town, cargo) -> max gold, processed per day
state = {(("Fennick", (0,0,0,0))): 250}
traces = {}
for d in range(1, 8):
    newstate = {}
    for (t, cargo), gold in state.items():
        c = list(cargo)
        p = [WORLD["prices"][t][g] for g in GOODS]
        fut = [u[d][t][g] for g in GOODS]
        # choose target cargo c1 maximizing gold1 + value(c1), where
        # gold1 = gold + sum p_i*c_i - sum p_i*c1_i  (net; sells fund buys)
        # = gold + sum p_i*c_i + sum c1_i (fut_i - p_i)
        # s.t. sum c1 <= CAP, and buy cost sum p_i*max(c1_i-c_i,0) <= gold + sum p_i*max(c_i-c1_i,0)
        # note gold1 = gold + sum p_i*max(c_i-c1_i,0) - sum p_i*max(c1_i-c_i,0)
        # maximize sum c1_i * fut_i + sum p_i*max(c_i-c1_i,0) - sum p_i*max(c1_i-c_i,0)
        # equivalently value: c1_i*fut_i + p_i*(c_i-c1_i) for all i (since if c1_i<c_i sell gives p_i which equals -p_i*(c1_i-c_i);
        # if c1_i>c_i gives -p_i*(c1_i-c_i) cost) -> yes exactly: sum_i [fut_i*c1_i - p_i*(c1_i - c_i)]
        # = const + sum_i c1_i (fut_i - p_i)
        # affordability: net spend <= gold  where net spend = sum p_i*max(c1_i-c_i,0) - sum p_i*max(c_i-c1_i,0)
        base = gold + sum(p[i]*c[i] for i in range(4))
        vals = [fut[i]-p[i] for i in range(4)]
        # unbounded knapsack per good (0..CAP each), capacity CAP, value vals[i], cost p[i] (for buys only)
        # budget depends on c1 via net spend; handle by DP over (cap, net_spend) where net_spend can be negative (net selling)
        # net_spend = sum_i p_i*(c1_i - c_i) can range from -sum p*c (>= -2400) to +2400. offset 2400.
        OFF = 2400
        NEG, POS = 2400, 2400
        dp = [dict() for _ in range(CAP+1)]
        # dp[k][ns] = max value for k units, net spend ns (ns in [-NEG, POS]); start: no goods, k=0, ns=0, val 0
        dp[0][0] = 0
        for i in range(4):
            ndp = [dict(x) for x in dp]
            for k in range(CAP+1):
                for ns, v in dp[k].items():
                    # add q of good i
                    q = 0
                    while True:
                        q += 1
                        if k + q > CAP: break
                        nns = ns + p[i]*q
                        if nns < -NEG or nns > POS: break
                        nv = v + vals[i]*q
                        if nv > ndp[k+q].get(nns, -1):
                            ndp[k+q][nns] = nv
            dp = ndp
        # choose best over k<=CAP, ns <= gold
        bestv, bestc1 = -1, None
        for k in range(CAP+1):
            for ns, v in dp[k].items():
                if ns <= gold and v > bestv:
                    bestv, bestc1 = v, (k, ns)
        # reconstruct not needed; we need actual c1. Redo with parent? Simpler: brute force c1 over reduced space:
        # Actually reconstruct: rerun knapsack storing the choice.
        dp2 = [dict() for _ in range(CAP+1)]
        pick = [dict() for _ in range(CAP+1)]
        dp2[0][0] = 0
        for i in range(4):
            ndp = [dict(x) for x in dp2]
            npk = [dict(x) for x in pick]
            for k in range(CAP+1):
                for ns, v in dp2[k].items():
                    q = 1
                    while True:
                        if k + q > CAP: break
                        nns = ns + p[i]*q
                        if nns < -NEG or nns > POS: break
                        nv = v + vals[i]*q
                        if nv > ndp[k+q].get(nns, -1):
                            ndp[k+q][nns] = nv
                            npk[k+q][nns] = (i, q, k, ns)
                        q += 1
            dp2, pick = ndp, npk
        bestv, bestkey = -1, None
        for k in range(CAP+1):
            for ns, v in dp2[k].items():
                if ns <= gold and v > bestv:
                    bestv, bestkey = v, (k, ns)
